args.query:
select c.name, coalesce(a.s,0) approved, coalesce(k.s,0) contracted, coalesce(a.s,0)-coalesce(k.s,0) diff from api.company c left join (select company_id, sum(amount) s from api.application ap join api.status st on st.id=ap.status_id where false group by 1) a on a.company_id=c.id left join (select 1 company_id, 0 s where false) k on k.company_id=c.id limit 0;
select column_name, table_name from information_schema.columns where table_schema='api' and table_name in ('application','status');
select pg_get_viewdef('api.limit_balance'::regclass);
